package org.brightstats.desktop;

import java.util.*;
import javafx.geometry.Insets;
import javafx.scene.control.*;
import javafx.scene.layout.*;
import javafx.stage.Window;
import org.brightstats.stats.*;

final class IpmaDialog {
    private final Dialog<ImportancePerformance.Options> dialog=new Dialog<>();private final ComboBox<String> target=new ComboBox<>();private final ComboBox<ImportancePerformance.Depth> depth=new ComboBox<>();private final ComboBox<ImportancePerformance.Units> units=new ComboBox<>();private final CheckBox declared=new CheckBox("Use the entered possible endpoints for every modeled indicator");private final Map<Integer,TextField[]> ranges=new LinkedHashMap<>();private final Map<Integer,CheckBox> reverse=new LinkedHashMap<>();private ImportancePerformance.Options result;
    IpmaDialog(Window owner,List<String> names,double[][] data,List<PlsSem.Block> blocks,List<PlsSem.Edge> edges,ImportancePerformance.Options previous){
        if(blocks.isEmpty())throw new IllegalArgumentException("Create an indicator model before IPMA.");dialog.initOwner(owner);dialog.setTitle("Importance–performance analysis");target.getItems().setAll(blocks.stream().map(PlsSem.Block::name).toList());target.getSelectionModel().select(previous!=null&&previous.target()<blocks.size()?previous.target():blocks.size()-1);depth.getItems().setAll(ImportancePerformance.Depth.values());depth.setValue(previous==null?ImportancePerformance.Depth.ALL_PREDECESSORS:previous.depth());units.getItems().setAll(ImportancePerformance.Units.values());units.setValue(previous==null?ImportancePerformance.Units.ORIGINAL_UNITS:previous.units());declared.setSelected(previous!=null&&!previous.ranges().isEmpty());Map<Integer,ImportancePerformance.Range> saved=new HashMap<>();if(previous!=null)for(var range:previous.ranges())saved.put(range.column(),range);TreeSet<Integer> columns=new TreeSet<>();for(var block:blocks)for(int column:block.columns())columns.add(column);
        GridPane grid=new GridPane();grid.setHgap(10);grid.setVgap(8);grid.addRow(0,UiAppearance.label("Indicator"),UiAppearance.label("Possible minimum"),UiAppearance.label("Possible maximum"),UiAppearance.label("Reverse code"));int row=1;for(int column:columns){if(column>=names.size())throw new IllegalArgumentException("IPMA indicator is unavailable.");double low=Double.POSITIVE_INFINITY,high=Double.NEGATIVE_INFINITY;for(double[] values:data){low=Math.min(low,values[column]);high=Math.max(high,values[column]);}var savedRange=saved.get(column);TextField minimum=new TextField(Double.toString(savedRange==null?low:savedRange.minimum())),maximum=new TextField(Double.toString(savedRange==null?high:savedRange.maximum()));minimum.setPrefColumnCount(10);maximum.setPrefColumnCount(10);minimum.disableProperty().bind(declared.selectedProperty().not());maximum.disableProperty().bind(declared.selectedProperty().not());CheckBox coding=new CheckBox();coding.setSelected(savedRange!=null&&savedRange.reverse());ranges.put(column,new TextField[]{minimum,maximum});reverse.put(column,coding);grid.addRow(row++,new Label(names.get(column)),minimum,maximum,coding);}
        Label guidance=UiAppearance.label("Confirm that higher coded values mean better performance. Reverse coding is applied before PLS estimation. Mixed-sign normalized weights require a coding/model review. Observed extrema are starting suggestions; use possible theoretical endpoints when known. Original-unit effects are not automatically effects per performance point when scales differ.");guidance.setWrapText(true);VBox form=new VBox(10,UiAppearance.label("Target construct"),target,UiAppearance.label("Predecessor scope"),depth,UiAppearance.label("Importance effect units"),units,declared,guidance,grid);form.setPadding(new Insets(12));ScrollPane scroll=new ScrollPane(form);scroll.setFitToWidth(true);Label error=new Label();error.setWrapText(true);VBox content=new VBox(8,scroll,error);VBox.setVgrow(scroll,Priority.ALWAYS);content.setPrefSize(730,620);dialog.getDialogPane().setContent(content);dialog.setResizable(true);dialog.getDialogPane().getButtonTypes().setAll(ButtonType.OK,ButtonType.CANCEL);dialog.getDialogPane().lookupButton(ButtonType.OK).addEventFilter(javafx.event.ActionEvent.ACTION,event->{result=null;try{int selected=target.getSelectionModel().getSelectedIndex();if(edges.stream().noneMatch(edge->edge.target()==selected))throw new IllegalArgumentException("Choose a target with at least one predecessor.");List<ImportancePerformance.Range> chosen=new ArrayList<>();for(int column:columns)if(declared.isSelected()||reverse.get(column).isSelected()){var fields=ranges.get(column);var range=new ImportancePerformance.Range(column,Double.parseDouble(fields[0].getText().trim()),Double.parseDouble(fields[1].getText().trim()),reverse.get(column).isSelected());for(double[] values:data)if(values[column]<range.minimum()||values[column]>range.maximum())throw new IllegalArgumentException("Entered range excludes observed values for "+names.get(column));chosen.add(range);}result=new ImportancePerformance.Options(selected,depth.getValue(),units.getValue(),chosen);}catch(Exception problem){event.consume();error.setText(problem.getMessage());}});dialog.setResultConverter(button->button==ButtonType.OK?result:null);
    }
    static Optional<ImportancePerformance.Options> show(Window owner,List<String> names,double[][] data,List<PlsSem.Block> blocks,List<PlsSem.Edge> edges,ImportancePerformance.Options previous){return new IpmaDialog(owner,names,data,blocks,edges,previous).dialog.showAndWait();}
    static ImportancePerformance.Options smokeTest(Window owner,List<String> names,double[][] data,List<PlsSem.Block> blocks,List<PlsSem.Edge> edges){var test=new IpmaDialog(owner,names,data,blocks,edges,null);test.dialog.show();test.target.getSelectionModel().select(0);((Button)test.dialog.getDialogPane().lookupButton(ButtonType.OK)).fire();if(!test.dialog.isShowing()||test.result!=null)throw new AssertionError("Root IPMA target accepted");test.target.getSelectionModel().select(blocks.size()-1);test.declared.setSelected(true);var first=test.ranges.values().iterator().next();String minimum=first[0].getText();first[0].setText(first[1].getText());((Button)test.dialog.getDialogPane().lookupButton(ButtonType.OK)).fire();if(!test.dialog.isShowing()||test.result!=null)throw new AssertionError("Collapsed IPMA range accepted");first[0].setText(minimum);((Button)test.dialog.getDialogPane().lookupButton(ButtonType.OK)).fire();if(test.dialog.getResult()==null)throw new AssertionError("IPMA settings lost");return test.dialog.getResult();}
}
